<script setup lang="ts">import{ref}from'vue';import{useMutation,useQuery,useQueryClient}from'@tanstack/vue-query';import{adminApi,type User,type UserInput}from'../api';import UserDialog from'../components/UserDialog.vue';import DsBadge from'@/shared/ui/DsBadge.vue';import DsButton from'@/shared/ui/DsButton.vue';import DsCard from'@/shared/ui/DsCard.vue';import DsPageHeader from'@/shared/ui/DsPageHeader.vue';import DsState from'@/shared/ui/DsState.vue';const qc=useQueryClient(),selected=ref<User|null>(null),open=ref(false);const q=useQuery({queryKey:['admin','users'],queryFn:adminApi.users});const roles=useQuery({queryKey:['admin','roles'],queryFn:adminApi.roles});const save=useMutation({mutationFn:(v:UserInput)=>selected.value?adminApi.updateUser(selected.value.PublicID,v):adminApi.createUser(v),onSuccess:async()=>{open.value=false;selected.value=null;await qc.invalidateQueries({queryKey:['admin','users']})}});function add(){selected.value=null;open.value=true}function edit(u:User){selected.value=u;open.value=true}</script><template><section><DsPageHeader eyebrow="ACCESS CONTROL" title="User Management" description="Manage people and their role assignments."><template #actions><DsButton @click="add">Add user</DsButton></template></DsPageHeader><DsCard class="panel"><DsState v-if="q.isPending.value" kind="loading"/><DsState v-else-if="q.isError.value" kind="error" title="Unable to load users"/><DsState v-else-if="!q.data.value?.length" kind="empty" title="No users yet"/><table v-else><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Roles</th><th></th></tr></thead><tbody><tr v-for="u in q.data.value" :key="u.PublicID"><td><strong>{{u.Name}}</strong></td><td>{{u.Email}}</td><td><DsBadge :tone="u.Status==='active'?'success':'neutral'">{{u.Status}}</DsBadge></td><td>{{u.Roles?.join(', ')||'—'}}</td><td><DsButton variant="secondary" @click="edit(u)">Edit</DsButton></td></tr></tbody></table></DsCard><UserDialog :open="open" :user="selected" :roles="roles.data.value??[]" :busy="save.isPending.value" @close="open=false" @save="save.mutate"/></section></template><style scoped>section{padding:32px}.panel{padding:0;overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:15px 18px;border-bottom:1px solid var(--ds-border);font-size:14px}th{color:var(--ds-text-muted);font-size:12px;text-transform:uppercase;letter-spacing:.05em}tbody tr:last-child td{border-bottom:0}td:last-child{text-align:right}@media(max-width:640px){section{padding:20px}}</style>